/// 🚪️ Drives a headless process future and retires its mounted native I/O owners.
#[cfg(not(target_arch = "wasm32"))]
pub(crate) fn drive_native_entrypoint<F: std::future::Future>(future: F) -> F::Output {
    use std::sync::atomic::Ordering;
    use std::task::Poll;
    let mut future = Some(Box::pin(future));
    let mut output = None;
    semio_framework_async::block_on(std::future::poll_fn(|context| {
        if let Some(active) = future.as_mut() {
            if let Poll::Ready(value) = active.as_mut().poll(context) {
                output = Some(value);
                future = None;
            }
        }
        crate::pump_renderer_io_sessions(16);
        let pending = crate::RENDERER_IO_SLOTS.iter().any(|slot| matches!(slot.state.load(Ordering::Acquire), crate::RENDERER_IO_LIVE | crate::RENDERER_IO_CHECKED_OUT));
        if !pending {
            if let Some(value) = output.take() { return Poll::Ready(value); }
        } else {
            context.waker().wake_by_ref();
        }
        Poll::Pending
    }))
}

/// ⌨️ Runs the native application with a caller-owned inventory of installed document services.
#[cfg(not(target_arch = "wasm32"))]
pub fn run_native_entrypoint(services: Vec<semio_framework_os_kernel::os_directory::client::InstalledServiceContributionV1>) {
    use crate::{run_native, run_smoke};
    use semio_framework_os_kernel::os_directory::identity::{claim_inherited_local_hub_credential, IdentityEnv};
    use std::env;
    use std::path::PathBuf;

    fn arg_value(flag: &str) -> Option<String> {
        env::args().position(|arg| arg == flag).and_then(|index| env::args().nth(index + 1))
    }


    #[cfg(unix)]
    fn inherited_credential_fd_is_closed() -> bool {
        unsafe extern "C" {
            fn fcntl(fd: i32, command: i32, ...) -> i32;
        }
        (unsafe { fcntl(3, 1) }) < 0
    }

    #[cfg(windows)]
    fn inherited_credential_fd_is_closed() -> bool {
        unsafe extern "C" {
            fn _get_osfhandle(fd: i32) -> isize;
        }
        (unsafe { _get_osfhandle(3) }) == -1
    }

    fn protected_credential_environment_is_absent() -> bool {
        env::vars_os().all(|(key, value)| {
            let key = key.to_string_lossy().to_ascii_uppercase();
            if key == "S_LOCAL_CREDENTIAL_FD" {
                return value == "3";
            }
            !(key == "S_USER"
                    || key == "VITE_S_USER"
                    || key == "S_HUB_URL"
                    || key.contains("TOKEN")
                    || key.contains("SESSION")
                    || key.contains("CREDENTIAL")
                    || key.contains("BEARER")
                    || key.contains("CAPABILITY")
                    || key.contains("AUTHORIZATION")
                    || key.contains("COOKIE"))
        })
    }

    fn benign_direct_child_environment_is_preserved() -> bool {
        env::var("SEMIO_DIRECT_CHILD_BENIGN").ok().as_deref() == Some("preserved")
    }

    if !protected_credential_environment_is_absent() {
        eprintln!("[TRACE] native protected credential environment rejected");
        std::process::exit(1);
    }
    if IdentityEnv::from_process_env().is_some() && claim_inherited_local_hub_credential("native").is_err() {
        eprintln!("[TRACE] native local credential claim failed");
        std::process::exit(1);
    }
    if env::args().any(|arg| arg == "--assert-no-local-credential-state") {
        std::process::exit(if inherited_credential_fd_is_closed() && protected_credential_environment_is_absent() && benign_direct_child_environment_is_preserved() { 0 } else { 1 });
    }
    if env::args().any(|arg| arg == "--credential-probe") {
        if !protected_credential_environment_is_absent() || !benign_direct_child_environment_is_preserved() {
            std::process::exit(1);
        }
        let status = env::current_exe()
            .ok()
            .and_then(|executable| std::process::Command::new(executable).arg("--assert-no-local-credential-state").env_remove("S_LOCAL_CREDENTIAL_FD").status().ok());
        if status.is_some_and(|status| status.success()) {
            println!("native-credential-probe-ok");
            std::process::exit(0);
        }
        std::process::exit(1);
    }
    if env::args().any(|arg| arg == "--socket-grant-probe") {
        let status = drive_native_entrypoint(crate::run_socket_grant_probe());
        if status == 0 {
            println!("native-socket-grant-probe-ok");
        }
        std::process::exit(status);
    }
    let mut descriptor = crate::boot_descriptor();
    let plugin_filter = arg_value("--plugin").unwrap_or_else(|| "studio".to_string());
    descriptor.plugin_variant = plugin_filter.clone();
    if let Some(app_id) = arg_value("--app") {
        descriptor.app_id = app_id;
    }
    if let Some(role) = arg_value("--role") {
        descriptor.app_role = role;
    }
    if let Some(mode) = arg_value("--mode") {
        descriptor.app_mode = mode;
    }
    if let Some(example) = arg_value("--example") {
        descriptor.app_example = example;
    }
    if let Some(brand) = arg_value("--brand") {
        descriptor.brand_id = brand;
    }
    if let Some(hub_url) = arg_value("--hub") {
        descriptor.hub = Some(crate::WgpuBootHub { hub_url, user: arg_value("--user").unwrap_or_default(), data_dir: arg_value("--data-dir").unwrap_or_default() });
    }
    if let Err(error) = crate::apply_boot_descriptor(descriptor) {
        eprintln!("native boot descriptor rejected: {error}");
        std::process::exit(1);
    }
    if let Some(registry_path) = arg_value("--scale") {
        let Some(wasm_path) = arg_value("--scale-wasm") else {
            eprintln!("[TRACE] --scale requires --scale-wasm <fixture.wasm>");
            std::process::exit(1);
        };
        let Some(report_path) = arg_value("--report") else {
            eprintln!("[TRACE] --scale requires --report <out.json>");
            std::process::exit(1);
        };
        let shard_count: u16 = arg_value("--shards").and_then(|v| v.parse().ok()).unwrap_or(8);
        std::process::exit(drive_native_entrypoint(crate::scale_bench::run(PathBuf::from(registry_path), PathBuf::from(wasm_path), shard_count, PathBuf::from(report_path))));
    }
    let modules_root = match env::var("SEMIO_PLUGIN_MODULES") {
        Ok(value) if !value.trim().is_empty() => PathBuf::from(value),
        _ => {
            eprintln!("SEMIO_PLUGIN_MODULES is unset: run through `bun nx run @semio-tech/framework-os-dev:run-<variant>-native-<profile>`");
            std::process::exit(2);
        }
    };
    if env::args().any(|arg| arg == "--smoke") {
        std::process::exit(drive_native_entrypoint(run_smoke(&plugin_filter, modules_root, services)));
    }
    run_native(&plugin_filter, modules_root, services);
}

fn drive_native_entrypoint<F>(future: F) { semio_framework_async::block_on(future); }
fn run_native_entrypoint() { drive_native_entrypoint(socket()); drive_native_entrypoint(scale()); drive_native_entrypoint(smoke()); }
fn drive_native_entrypoint<F>(future: F) { }
